```python
verification_contact_pages = []
verification_contacts = []
verification_page_index = 0
while True:
    verification_page = apis.phone.search_contacts(access_token=phone_access_token, query="", relationship="roommate", page_index=verification_page_index, page_limit=page_limit)
    verification_contact_pages.append(verification_page)
    verification_contacts.extend(verification_page)
    if len(verification_page) < page_limit:
        break
    verification_page_index += 1
receipt_after_requests = apis.file_system.show_file(file_path=selected_receipt_record["path"], access_token=file_system_access_token)

if len(payment_request_results) != len(payment_request_plan):
    raise RuntimeError("The number of creation responses does not match the reviewed request plan")
current_roommate_emails = {str(contact.get("email", "")).strip().lower() for contact in verification_contacts if contact.get("email")}
returned_request_ids = []
verified_requests = []
for planned, result in zip(payment_request_plan, payment_request_results):
    if result["user_email"] != planned["user_email"] or result["amount"] != planned["amount"] or result["description"] != "For electricity bill.":
        raise RuntimeError("A submitted request differs from the reviewed plan")
    if planned["user_email"].lower() not in current_roommate_emails:
        raise RuntimeError("A request recipient is no longer present in the re-queried roommate contacts")
    response = result["response"]
    request_id = response.get("payment_request_id") if isinstance(response, dict) else None
    if request_id is None:
        raise RuntimeError("A Venmo creation response lacks a payment request ID")
    returned_request_ids.append(request_id)
    verified_requests.append({"payment_request_id": request_id, "user_email": result["user_email"], "amount": result["amount"], "description": result["description"], "message": response.get("message")})
if len(set(returned_request_ids)) != len(returned_request_ids):
    raise RuntimeError("Venmo returned duplicate payment request IDs")
if str(receipt_after_requests.get("content", "")) != str(selected_receipt_record.get("content", "")):
    raise RuntimeError("The re-queried receipt content differs from the source used for the split")
reloaded_amount_choice = best_labeled_amount(receipt_after_requests.get("content", ""))
if reloaded_amount_choice is None or abs(float(reloaded_amount_choice[1]) - bill_amount) > 0.005:
    raise RuntimeError("The re-queried receipt does not support the reviewed bill amount")
verification_summary = {"receipt_path": receipt_after_requests.get("path"), "bill_amount": bill_amount, "participant_count": participant_count, "expected_request_count": len(payment_request_plan), "verified_request_count": len(verified_requests), "requests": verified_requests}
print(verification_summary)
