            after_char = lower[after_position] if after_position < len(lower) else " "
            if (before_char.isalnum() or after_char.isalnum()) and label in ("total", "amount", "paid"):
                cursor = found + len(label)
                continue
            window = source[after_position:after_position + 180]
            for token in numeric_tokens(window):
                value = token["value"]
                if value <= 0:
                    continue
                score = 2400 - label_index * 120 - min(token["start"], 160)
                if token["has_currency"]:
                    score += 180
                if token["decimal_places"] == 2:
                    score += 80
                if 1900 <= value <= 2100 and not token["has_currency"]:
                    score -= 900
                if value > 1000000 and not token["has_currency"]:
                    score -= 900
                scored.append((score, value, label, token["raw"]))
            cursor = found + len(label)
    if not scored:
        for token in numeric_tokens(source):
            value = token["value"]
            if value <= 0:
                continue
            nearby = lower[max(0, token["start"] - 50):token["start"] + 50]
            keyword_score = sum(90 for keyword in ("total", "amount", "paid", "charge", "bill") if keyword in nearby)
            score = keyword_score + (180 if token["has_currency"] else 0) + (70 if token["decimal_places"] == 2 else 0)
            if 1900 <= value <= 2100 and not token["has_currency"]:
                score -= 900
            if token["has_currency"] or token["decimal_places"] == 2 or keyword_score:
                scored.append((score, value, "monetary context", token["raw"]))
    if not scored:
        return None
    return max(scored, key=lambda item: item[0])

receipt_options = []
for record in receipt_file_records:
    content = str(record.get("content", ""))
    path = str(record.get("path", ""))
    combined = (path + "\n" + content).lower()
    amount_choice = best_labeled_amount(content)
    if amount_choice is None:
        continue
    selection_score = amount_choice[0]
    if "electric" in combined:
        selection_score += 700
    if "receipt" in combined:
        selection_score += 160
    if "bill" in combined:
        selection_score += 120
    if target_month_terms and any(term in combined for term in target_month_terms):
        selection_score += 5000
    receipt_options.append({"record": record, "selection_score": selection_score, "amount_choice": amount_choice})
if not receipt_options:
    raise RuntimeError("No receipt candidate contained a positive labeled monetary amount")
receipt_options.sort(key=lambda item: (item["selection_score"], str(item["record"].get("updated_at", "")), str(item["record"].get("path", ""))), reverse=True)
selected_receipt_option = receipt_options[0]
selected_receipt_record = selected_receipt_option["record"]
bill_amount = round(float(selected_receipt_option["amount_choice"][1]), 2)

selected_roommates = []
seen_roommate_emails = set()
own_email = str(supervisor_profile.get("email", "")).strip().lower()
for contact in roommate_contacts:
    email = str(contact.get("email", "")).strip()
    email_key = email.lower()
    if email and email_key != own_email and email_key not in seen_roommate_emails:
        seen_roommate_emails.add(email_key)
        selected_roommates.append(contact)
if not selected_roommates:
    raise RuntimeError("No roommate contact with a usable email was found")
participant_count = len(selected_roommates) + 1
unrounded_share = bill_amount / participant_count
share_amount = round(unrounded_share, 2)
if bill_amount <= 0 or share_amount <= 0:
    raise RuntimeError("The derived bill share must be positive")
payment_request_plan = []
for contact in selected_roommates:
    payment_request_plan.append({
        "contact_id": contact.get("contact_id"),
        "name": (str(contact.get("first_name", "")) + " " + str(contact.get("last_name", ""))).strip(),
        "user_email": str(contact.get("email", "")).strip(),
        "amount": share_amount,
        "description": "For electricity bill.",
    })
print({"receipt_path": selected_receipt_record.get("path"), "amount_evidence_label": selected_receipt_option["amount_choice"][2], "bill_amount": bill_amount, "participant_count": participant_count, "share_amount": share_amount, "roommate_requests": payment_request_plan})
